b217text10"]={["arg1"]=[[文本输出]],["arg2"]=[[眼前吊桥在山崖之间摇摇欲断，你运功一跃，轻踏吊桥绳索，听得绳索一动，后便轻松的抵达到了对面。]],["id"]=[[rlt_fb217text10]]},["rlt_fb217text11"]={["arg1"]=[[文本输出]],["arg2"]=[[你试着朝大雕靠近，它忽然煽动翅膀，闪身飞起，没了踪影。]],["id"]=[[rlt_fb217text11]]},["rlt_fb217text12"]={["arg1"]=[[文本输出]],["arg2"]=[[你本觉得这大雕通人性想要靠近细看，谁知它振翅而上，突然向你袭来，将你打回了山峰。]],["id"]=[[rlt_fb217text12]]},["rlt_fb217text13"]={["arg1"]=[[文本输出]],["arg2"]=[[你欲向前靠近却被大雕发现了，你被打下山峰的事让你心有余悸不敢再向前靠近。]],["id"]=[[rlt_fb217text13]]},["rlt_fb217text14"]={["arg1"]=[[文本输出]],["arg2"]=[[你本以为峭壁险峻无人能至，一步踏错则跌入万丈深渊，心中大有感慨，却未料早有先人在此刻下壁文。]],["id"]=[[rlt_fb217text14]]},["rlt_fb217text15"]={["arg1"]=[[文本输出]],["arg2"]=[[你细细读着这壁上的诗文，脑中忽显现一阵幻影，虚化出当年先人在此刻下壁文的一情一景，乃至他何时发劲儿，何时收势。四肢不由发汗，方明白：武无极境，天外有人。]],["id"]=[[rlt_fb217text15]]},["rlt_fb217text2"]={["arg1"]=[[文本输出]],["arg2"]=[[一旁的三刀客拦住了你，并指了指外头挂着的旌旗。]],["id"]=[[rlt_fb217text2]]},["rlt_fb217text3"]={["arg1"]=[[文本输出]],["arg2"]=[[你倒了一杯茶，这茶十分特殊，入口香甜后味却十分苦涩，不同于寻常的茶。]],["id"]=[[rlt_fb217text3]]},["rlt_fb217text4"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL三刀客：好武艺，阁下可以喝茶了！]],["id"]=[[rlt_fb217text4]]},["rlt_fb217text5"]={["arg1"]=[[文本输出]],["arg2"]=[[神秘车夫递给你了一块黑布，亲眼看着你蒙上双目才将你送上马车，之后你忽然觉得四肢无力，再醒来时已经回到了平安小镇。]],["id"]=[[rlt_fb217text5]]},["rlt_fb217text6"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL霓雾：少侠武艺尚佳，日后有缘再见。]],["id"]=[[rlt_fb217text6]]},["rlt_fb217text7"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL任通纪：大侠武艺高超，老夫十分佩服。]],["id"]=[[rlt_fb217text7]]},["rlt_fb217text8"]={["arg1"]=[[文本输出]],["arg2"]=[[眼前吊桥在山崖之间摇摇欲断，你运功一跃，轻踏吊桥绳索，听得绳索一动，后便轻松的抵达到了对面。]],["id"]=[[rlt_fb217text8]]},["rlt_fb217text9"]={["arg1"]=[[文本输出]],["arg2"]=[[你运气一沉，刚刚用轻功踏上了吊桥上的木板，那木板便断落悬崖，你只好退了回来。]],["id"]=[[rlt_fb217text9]]},["rlt_fb217text99"]={["arg1"]=[[文本输出]],["id"]=[[rlt_fb217text99]]},["rlt_fbcs"]={["arg1"]=[[副本跳转]],["arg2"]=[[fb205]],["arg3"]=[[fb205_26]],["arg4"]=100,["id"]=[[rlt_fbcs]],["level"]=2},["rlt_lcbj1"]={["arg1"]=[[地图标记设置]],["arg2"]=[[lcbj]],["arg3"]=1,["id"]=[[rlt_lcbj1]]},["rlt_lcjgj1"]={["arg1"]=[[结果集]],["arg2"]=[[delete;fb217text99]],["id"]=[[rlt_lcjgj1]]},[